ALTER TABLE public.tasks ADD COLUMN completed_at timestamptz;
UPDATE public.tasks t SET completed_at = (SELECT max(l.created_at) FROM public.task_activity_logs l WHERE l.task_id=t.id AND l.event='Task completed') WHERE t.status='done';
CREATE FUNCTION public.record_task_completion() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN IF TG_OP='INSERT' THEN NEW.completed_at:=CASE WHEN NEW.status='done' THEN now() ELSE NULL END; ELSIF NEW.status IS DISTINCT FROM OLD.status THEN NEW.completed_at:=CASE WHEN NEW.status='done' THEN now() ELSE NULL END; ELSE NEW.completed_at:=OLD.completed_at; END IF; RETURN NEW; END $$;
REVOKE ALL ON FUNCTION public.record_task_completion() FROM PUBLIC, anon, authenticated;
CREATE TRIGGER record_task_completion BEFORE INSERT OR UPDATE ON public.tasks FOR EACH ROW EXECUTE FUNCTION public.record_task_completion();
CREATE INDEX tasks_workspace_created_idx ON public.tasks(workspace_id,created_at);
CREATE INDEX tasks_workspace_completed_idx ON public.tasks(workspace_id,completed_at) WHERE completed_at IS NOT NULL;
CREATE INDEX task_activity_completion_idx ON public.task_activity_logs(task_id,created_at) WHERE event='Task completed';
CREATE FUNCTION public.workspace_analytics(p_workspace uuid,p_from date,p_to date,p_today date,p_project uuid DEFAULT NULL,p_member uuid DEFAULT NULL,p_status text DEFAULT NULL,p_priority text DEFAULT NULL,p_offset integer DEFAULT 0,p_limit integer DEFAULT 25) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY INVOKER SET search_path=public AS $$
DECLARE result jsonb;
BEGIN
 IF auth.uid() IS NULL OR public.workspace_role(p_workspace) IS NULL THEN RAISE EXCEPTION 'Workspace access denied' USING ERRCODE='42501'; END IF;
 IF p_from IS NULL OR p_to IS NULL OR p_to<p_from OR p_to-p_from>3660 OR p_today IS NULL OR p_offset<0 OR p_limit<1 OR p_limit>500 THEN RAISE EXCEPTION 'Invalid reporting range or page'; END IF;
 WITH ps AS (SELECT * FROM public.projects WHERE workspace_id=p_workspace AND status<>'Archived' AND (p_project IS NULL OR id=p_project)),
 base AS (SELECT t.* FROM public.tasks t JOIN ps p ON p.id=t.project_id WHERE (p_member IS NULL OR t.assignee_id=p_member) AND (p_status IS NULL OR t.status=p_status) AND (p_priority IS NULL OR t.priority=p_priority)),
 ts AS (SELECT * FROM base WHERE (created_at AT TIME ZONE 'UTC')::date BETWEEN p_from AND p_to),
 ms AS (SELECT m.* FROM public.milestones m JOIN ps ON ps.id=m.project_id WHERE (p_member IS NULL OR m.owner_id=p_member) AND (m.created_at AT TIME ZONE 'UTC')::date BETWEEN p_from AND p_to),
 issues AS (
 SELECT t.id,t.project_id,t.title,'task'::text kind,'Overdue task'::text category,CASE WHEN t.priority IN ('High','Urgent') THEN 'Critical' ELSE 'High' END severity,'Task deadline has passed'::text reason,'Review deadline and unblock remaining work'::text action FROM ts t WHERE t.status<>'done' AND t.due_date<p_today
 UNION ALL SELECT t.id,t.project_id,t.title,'task','Blocked task','High','An unfinished prerequisite blocks this task','Complete or review the prerequisite' FROM ts t WHERE t.status<>'done' AND EXISTS(SELECT 1 FROM public.task_dependencies d JOIN public.tasks b ON b.id=d.predecessor_task_id WHERE d.successor_task_id=t.id AND d.dependency_type='FS' AND b.status<>'done')
 UNION ALL SELECT t.id,t.project_id,t.title,'task','Dependency conflict','High','Task starts before its prerequisite finishes','Confirm and adjust conflicting dates' FROM ts t WHERE t.status<>'done' AND EXISTS(SELECT 1 FROM public.task_dependencies d JOIN public.tasks b ON b.id=d.predecessor_task_id WHERE d.successor_task_id=t.id AND d.dependency_type='FS' AND t.start_date<b.due_date)
 UNION ALL SELECT t.id,t.project_id,t.title,'task','Unassigned task','Medium','Active task has no assignee','Assign an accountable team member' FROM ts t WHERE t.status<>'done' AND t.assignee_id IS NULL
 UNION ALL SELECT t.id,t.project_id,t.title,'task','Missing due date','Low','Active task has no deadline','Agree a due date with the owner' FROM ts t WHERE t.status<>'done' AND t.due_date IS NULL
 UNION ALL SELECT t.id,t.project_id,t.title,'task','Outside project schedule','Medium','Task dates fall outside project dates','Review the task or project date range' FROM ts t JOIN ps p ON p.id=t.project_id WHERE t.status<>'done' AND (t.start_date<p.start_date OR t.due_date>p.due_date)
 UNION ALL SELECT m.id,m.project_id,m.title,'milestone','Delayed milestone','Critical','Milestone is overdue or marked delayed','Review required tasks and agree a recovery plan' FROM ms m WHERE m.status<>'Completed' AND (m.due_date<p_today OR m.status='Delayed')
 UNION ALL SELECT p.id,p.id,p.name,'project','Project deadline','High','Project deadline is within seven days or overdue with incomplete work','Review remaining tasks and milestone commitments' FROM ps p WHERE p.status<>'Completed' AND p.due_date<=p_today+7
 UNION ALL SELECT p.id,p.id,p.name,'project','Invalid project dates','High','Project due date precedes its start','Correct the project date range' FROM ps p WHERE p.due_date<p.start_date
 ),
 project_rows AS (SELECT p.*, (SELECT count(*) FROM public.tasks t WHERE t.project_id=p.id) task_count,(SELECT count(*) FROM public.tasks t WHERE t.project_id=p.id AND t.status='done') done_count,
 CASE WHEN p.status='Completed' THEN 'Completed' WHEN p.due_date<p_today OR EXISTS(SELECT 1 FROM public.tasks t WHERE t.project_id=p.id AND t.status<>'done' AND t.priority IN ('High','Urgent') AND t.due_date<p_today) OR EXISTS(SELECT 1 FROM public.milestones m WHERE m.project_id=p.id AND m.status<>'Completed' AND (m.due_date<p_today OR m.status='Delayed')) THEN 'Delayed' WHEN EXISTS(SELECT 1 FROM public.tasks t WHERE t.project_id=p.id AND t.status<>'done' AND (t.priority IN ('High','Urgent') AND t.due_date BETWEEN p_today AND p_today+7 OR EXISTS(SELECT 1 FROM public.task_dependencies d JOIN public.tasks b ON b.id=d.predecessor_task_id WHERE d.successor_task_id=t.id AND b.status<>'done') OR EXISTS(SELECT 1 FROM public.task_dependencies d JOIN public.tasks b ON b.id=d.predecessor_task_id WHERE d.successor_task_id=t.id AND t.start_date<b.due_date))) OR p.due_date BETWEEN p_today AND p_today+7 THEN 'At Risk' WHEN NOT EXISTS(SELECT 1 FROM public.tasks t WHERE t.project_id=p.id AND t.status IN ('doing','review','done')) THEN 'Not Started' ELSE 'On Track' END health,
 (SELECT count(*) FROM public.milestones m WHERE m.project_id=p.id) milestone_count,(SELECT count(*) FROM public.milestones m WHERE m.project_id=p.id AND m.status='Completed') milestone_done
 FROM ps p WHERE (p.created_at AT TIME ZONE 'UTC')::date BETWEEN p_from AND p_to),
 team_rows AS (SELECT wm.user_id,coalesce(pr.full_name,pr.email,'Team member') name,wm.role,count(t.id) assigned,count(t.id) FILTER(WHERE t.status='done') completed,count(t.id) FILTER(WHERE t.status='doing') in_progress,count(t.id) FILTER(WHERE t.status<>'done') active,count(t.id) FILTER(WHERE t.status<>'done' AND t.due_date<p_today) overdue,coalesce(sum(CASE WHEN t.status<>'done' THEN coalesce(nullif(t.estimated_effort,0),1)*CASE t.priority WHEN 'Urgent' THEN 2 WHEN 'High' THEN 1.5 WHEN 'Medium' THEN 1 ELSE 0.75 END ELSE 0 END),0) workload FROM public.workspace_members wm LEFT JOIN public.profiles pr ON pr.id=wm.user_id LEFT JOIN ts t ON t.assignee_id=wm.user_id WHERE wm.workspace_id=p_workspace AND (p_member IS NULL OR wm.user_id=p_member) GROUP BY wm.user_id,pr.full_name,pr.email,wm.role),
 trend AS (SELECT (completed_at AT TIME ZONE 'UTC')::date date,count(*) value FROM base WHERE status='done' AND (completed_at AT TIME ZONE 'UTC')::date BETWEEN p_from AND p_to GROUP BY 1),
 page AS (SELECT t.*,p.name project_name FROM ts t JOIN ps p ON p.id=t.project_id ORDER BY t.created_at DESC,t.id LIMIT p_limit OFFSET p_offset)
 SELECT jsonb_build_object(
 'generated_at',now(),'projects',coalesce((SELECT jsonb_agg(to_jsonb(p) || jsonb_build_object('progress',CASE WHEN task_count=0 THEN 0 ELSE floor(done_count*100.0/task_count) END,'reason',CASE health WHEN 'Completed' THEN 'Project status is Completed' WHEN 'Delayed' THEN 'Project deadline or critical task/milestone is overdue' WHEN 'At Risk' THEN 'Approaching deadlines, blocked work or dependency conflicts' WHEN 'Not Started' THEN 'No task has reached in progress, review or done' ELSE 'No critical overdue work or dependency conflicts detected' END)) FROM project_rows p),'[]'::jsonb),
 'kpis',jsonb_build_object('projects',(SELECT count(*) FROM project_rows),'active_projects',(SELECT count(*) FROM project_rows WHERE status='Active'),'completed_projects',(SELECT count(*) FROM project_rows WHERE status='Completed'),'tasks',(SELECT count(*) FROM ts),'done',(SELECT count(*) FROM ts WHERE status='done'),'overdue',(SELECT count(*) FROM ts WHERE status<>'done' AND due_date<p_today),'deadlines',(SELECT count(*) FROM ts WHERE status<>'done' AND due_date BETWEEN p_today AND p_today+7)+(SELECT count(*) FROM ms WHERE status<>'Completed' AND due_date BETWEEN p_today AND p_today+7)+(SELECT count(*) FROM ps WHERE status<>'Completed' AND due_date BETWEEN p_today AND p_today+7),'in_progress',(SELECT count(*) FROM ts WHERE status='doing'),'blocked',(SELECT count(*) FROM issues WHERE category='Blocked task'),'completed_in_period',(SELECT coalesce(sum(value),0) FROM trend),'previous_created',(SELECT count(*) FROM base WHERE (created_at AT TIME ZONE 'UTC')::date BETWEEN p_from-(p_to-p_from+1) AND p_from-1),'previous_completed',(SELECT count(*) FROM base WHERE status='done' AND (completed_at AT TIME ZONE 'UTC')::date BETWEEN p_from-(p_to-p_from+1) AND p_from-1),'average_hours',(SELECT round(avg(extract(epoch FROM completed_at-created_at)/3600)::numeric,1) FROM base WHERE status='done' AND completed_at>=created_at AND (completed_at AT TIME ZONE 'UTC')::date BETWEEN p_from AND p_to),'unknown_completion',(SELECT count(*) FROM base WHERE status='done' AND completed_at IS NULL)),
 'statuses',coalesce((SELECT jsonb_agg(x) FROM (SELECT status name,count(*) value FROM ts GROUP BY status) x),'[]'::jsonb), 'priorities',coalesce((SELECT jsonb_agg(x) FROM (SELECT priority name,count(*) value FROM ts GROUP BY priority) x),'[]'::jsonb),'trend',coalesce((SELECT jsonb_agg(trend ORDER BY date) FROM trend),'[]'::jsonb), 'team',coalesce((SELECT jsonb_agg(team_rows) FROM team_rows),'[]'::jsonb),
 'milestone_stats',jsonb_build_object('total',(SELECT count(*) FROM ms),'completed',(SELECT count(*) FROM ms WHERE status='Completed'),'upcoming',(SELECT count(*) FROM ms WHERE status='Upcoming'),'delayed',(SELECT count(*) FROM ms WHERE status<>'Completed' AND (status='Delayed' OR due_date<p_today)),'this_week',(SELECT count(*) FROM ms WHERE status<>'Completed' AND due_date BETWEEN p_today AND p_today+(7-extract(isodow FROM p_today)::integer))),
 'milestones',coalesce((SELECT jsonb_agg(x) FROM (SELECT m.*,p.name project_name,(SELECT count(*) FROM public.milestone_tasks l WHERE l.milestone_id=m.id) required_tasks,(SELECT count(*) FROM public.milestone_tasks l JOIN public.tasks t ON t.id=l.task_id WHERE l.milestone_id=m.id AND t.status='done') completed_tasks FROM ms m JOIN ps p ON p.id=m.project_id ORDER BY m.due_date NULLS LAST,m.id LIMIT p_limit OFFSET p_offset)x),'[]'::jsonb),'milestone_total',(SELECT count(*) FROM ms),
 'risks',coalesce((SELECT jsonb_agg(x) FROM (SELECT * FROM issues ORDER BY CASE severity WHEN 'Critical' THEN 0 WHEN 'High' THEN 1 WHEN 'Medium' THEN 2 ELSE 3 END,id,category LIMIT p_limit OFFSET p_offset)x),'[]'::jsonb),'risk_total',(SELECT count(*) FROM issues),'tasks',coalesce((SELECT jsonb_agg(page) FROM page),'[]'::jsonb),'task_total',(SELECT count(*) FROM ts),
 'deadlines',coalesce((SELECT jsonb_agg(x) FROM (SELECT t.id,t.project_id,t.title,t.due_date date,'task' kind FROM ts t WHERE status<>'done' AND due_date<=p_today+7 UNION ALL SELECT m.id,m.project_id,m.title,m.due_date,'milestone' FROM ms m WHERE status<>'Completed' AND (due_date<=p_today+7 OR status='Delayed') UNION ALL SELECT p.id,p.id,p.name,p.due_date,'project' FROM ps p WHERE status<>'Completed' AND due_date<=p_today+7 ORDER BY date NULLS LAST,id LIMIT p_limit OFFSET p_offset)x),'[]'::jsonb)) INTO result;
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION public.workspace_analytics(uuid,date,date,date,uuid,uuid,text,text,integer,integer) FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.workspace_analytics(uuid,date,date,date,uuid,uuid,text,text,integer,integer) TO authenticated;